import {europeanCountries,normalize,cityAliases,popularDestinations} from './destinations.js';
import {koreanPlaceName} from './korean-place.js';
let quick,index,seq=0;const cache=new Map();
const hashes=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.codePointAt(0),16777619)>>>0;return[h%16384,(((h>>>16)^h)>>>0)%16384]};
async function rows(path){if(cache.has(path))return cache.get(path);let r=await fetch('cities/'+path);if(!r.ok)throw Error();let data=JSON.parse(await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).text());if(cache.size>=16)cache.delete(cache.keys().next().value);cache.set(path,data);return data}
function result(rows,q,code){return rows.filter(r=>(!code||r.code===code)).sort((a,b)=>(normalize(a.ko||a.name)===q?-1:0)-(normalize(b.ko||b.name)===q?-1:0)||b.population-a.population).slice(0,60).map(r=>({...r,ko:cityAliases.find(([,en])=>normalize(en)===normalize(r.name))?.[0]||({'Istanbul':'이스탄불','Saint Petersburg':'상트페테르부르크','Kyiv':'키이우','Kharkiv':'하르키우'}[r.name])||r.ko||koreanPlaceName(r.ascii||r.name),country:europeanCountries.find(c=>c.code===r.code)?.name}))}
onmessage=async({data})=>{const token=++seq,q=normalize(data.q),code=data.code;try{quick??=await fetch('cities.json').then(r=>r.json()).then(a=>a.map(r=>({id:r[0],code:r[1],name:r[2],ko:r[3],latitude:r[4],longitude:r[5],region:r[6],population:r[7],search:r[8]})));if(token!==seq)return;const aliases=cityAliases.filter(([ko])=>normalize(ko).includes(q)).map(([,en])=>normalize(en));let found=quick.filter(r=>(!code||r.code===code)&&(!q||normalize(r.ko+' '+r.name+' '+r.search).includes(q)||aliases.some(a=>normalize(r.name)===a)));postMessage({token:data.token,rows:result(found,q,code),loading:!!q});if(!q){if(!code)postMessage({token:data.token,rows:popularDestinations.map(c=>({id:c.id,code:c.code,ko:c.city,name:c.english,country:c.country,latitude:c.latitude,longitude:c.longitude})),loading:false});return;}index??=await fetch('cities/index.json').then(r=>r.json());if(token!==seq)return;const queryVariants=[q,...aliases];const candidates=index.chunks.filter(c=>{if(code&&c.code!==code)return false;if(/[가-힣]/.test(data.q))return true;const bits=Uint8Array.from(atob(c.bloom),c=>c.charCodeAt(0));return queryVariants.some(v=>{const grams=Array.from({length:Math.max(0,v.length-2)},(_,i)=>v.slice(i,i+3));return !grams.length||grams.every(g=>hashes(g).every(h=>(bits[h>>>3]&(1<<(h%8)))!==0))})});let unique=new Map(found.map(r=>[r.id,r]));for(let i=0;i<candidates.length;i+=8){if(token!==seq)return;for(const group of await Promise.all(candidates.slice(i,i+8).map(c=>rows(c.path))))for(const r of group)if(r.search.includes(q)||aliases.some(a=>normalize(r.name)===a||normalize(r.ascii)===a)||normalize(r.ko||koreanPlaceName(r.ascii)).includes(q))unique.set(r.id,r)}if(token===seq)postMessage({token:data.token,rows:result([...unique.values()],q,code),loading:false,total:unique.size})}catch{postMessage({token:data.token,error:true})}};
